solutions.The fanout census:
SELECT COUNT(*) AS rows
FROM orders o
JOIN order_items oi ON oi.order_id = o.id;

solutions.Distinct orderers:
SELECT DISTINCT oi.order_id AS id
FROM order_items oi
ORDER BY id;

solutions.The audit that found nothing:
SELECT
  (SELECT COUNT(*) FROM customers c LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL) AS customer_gaps,
  (SELECT COUNT(*) FROM order_items oi LEFT JOIN products p ON p.id = oi.product_id WHERE p.id IS NULL) AS item_gaps;

solutions.Commit the crime:
SELECT ROUND(SUM(o.total), 2) AS inflated
FROM orders o
JOIN order_items oi ON oi.order_id = o.id;

solutions.Count the raw pile:
SELECT COUNT(*) AS pile FROM (
  SELECT status FROM orders
  UNION ALL
  SELECT category FROM products
);

solutions.Region roll-up across both tables:
SELECT region, COUNT(*) AS n FROM (
  SELECT region FROM customers
  UNION ALL
  SELECT region FROM suppliers
) GROUP BY region
ORDER BY region;

solutions.Count each source:
SELECT kind, COUNT(*) AS n FROM (
  SELECT 'customer' AS kind FROM customers
  UNION ALL
  SELECT 'supplier' AS kind FROM suppliers
) GROUP BY kind
ORDER BY kind;

solutions.Filtering the pile:
SELECT person, place FROM (
  SELECT name AS person, city AS place FROM customers
  UNION ALL
  SELECT name, region FROM suppliers
) WHERE place = 'Berlin'
ORDER BY person;

solutions.How much overlap:
SELECT COUNT(*) AS overlap FROM (
  SELECT DISTINCT customer_id FROM orders WHERE status = 'delivered'
  INTERSECT
  SELECT DISTINCT customer_id FROM orders WHERE status = 'cancelled'
);

solutions.The union wing:
SELECT COUNT(*) AS either FROM (
  SELECT DISTINCT customer_id FROM orders WHERE status = 'delivered'
  UNION
  SELECT DISTINCT customer_id FROM orders WHERE status = 'cancelled'
);

solutions.Three operations, one audit:
SELECT COUNT(*) AS sym FROM (
  SELECT customer_id FROM (
    SELECT DISTINCT customer_id FROM orders WHERE status = 'delivered'
    EXCEPT
    SELECT DISTINCT customer_id FROM orders WHERE status = 'cancelled'
  )
  UNION ALL
  SELECT customer_id FROM (
    SELECT DISTINCT customer_id FROM orders WHERE status = 'cancelled'
    EXCEPT
    SELECT DISTINCT customer_id FROM orders WHERE status = 'delivered'
  )
);

solutions.Count the silent NULLs:
SELECT COUNT(*) AS unlabeled FROM (
  SELECT CASE WHEN status = 'cancelled' THEN 'dead' END AS tag
  FROM orders
) WHERE tag IS NULL;

solutions.Three patterns, one row:
SELECT
  (SELECT COUNT(*) FROM (
     SELECT customer_id FROM orders GROUP BY customer_id HAVING SUM(total) >= 3000
  )) AS high_tiers,
  (SELECT COUNT(*) FROM customers) + (SELECT COUNT(*) FROM suppliers) AS stacked_names,
  (SELECT COUNT(*) FROM (
     SELECT DISTINCT customer_id FROM orders WHERE status = 'delivered'
     EXCEPT
     SELECT DISTINCT customer_id FROM orders WHERE status = 'cancelled'
  )) AS except_first;

solutions.The stacked ledger:
SELECT id, total, kind FROM (
  SELECT id, total, 'done' AS kind FROM (
    SELECT * FROM orders WHERE status = 'delivered' ORDER BY total DESC, id ASC LIMIT 3
  )
  UNION ALL
  SELECT id, total, 'open' AS kind FROM orders WHERE status = 'pending'
)
ORDER BY kind, total DESC, id;

solutions.Above the average shelf:
SELECT name, price FROM products
WHERE price > (SELECT AVG(price) FROM products)
ORDER BY price DESC;

solutions.The cancelled club:
SELECT name FROM customers
WHERE id IN (SELECT customer_id FROM orders WHERE status = 'cancelled')
ORDER BY name;

solutions.Clean records:
SELECT name FROM customers
WHERE id NOT IN (SELECT customer_id FROM orders WHERE status = 'cancelled')
ORDER BY name;

solutions.No shipments on record:
SELECT c.name FROM customers c
WHERE NOT EXISTS (
  SELECT 1 FROM orders o
  WHERE o.customer_id = c.id AND o.status = 'shipped'
)
ORDER BY c.name;

solutions.Count the cancelled club:
SELECT COUNT(*) AS with_cancelled FROM customers c
WHERE EXISTS (
  SELECT 1 FROM orders o
  WHERE o.customer_id = c.id AND o.status = 'cancelled'
);

solutions.The empty ledger:
SELECT p.name FROM products p
WHERE NOT EXISTS (
  SELECT 1 FROM order_items oi
  WHERE oi.product_id = p.id
)
ORDER BY p.name;

solutions.Count via CTE:
WITH spend AS (
  SELECT customer_id, SUM(total) AS s FROM orders GROUP BY customer_id
)
SELECT COUNT(*) AS big_spenders FROM spend WHERE s > 1000;

solutions.The two-stage chain:
WITH spend AS (
  SELECT customer_id, SUM(total) AS s FROM orders GROUP BY customer_id
), big AS (
  SELECT * FROM spend WHERE s > 2000
)
SELECT c.name, b.s
FROM big b JOIN customers c ON c.id = b.customer_id
ORDER BY b.s DESC;

solutions.Surge months:
WITH monthly AS (
  SELECT strftime('%Y-%m', created_at) AS mon, COUNT(*) AS n
  FROM orders GROUP BY mon
)
SELECT mon, n FROM monthly WHERE n > 8 ORDER BY mon;

solutions.Handle extraction:
SELECT name, SUBSTR(email, 1, INSTR(email, '@') - 1) AS handle
FROM customers
ORDER BY name;

solutions.Whole-price shelf tags:
SELECT name, price, CAST(price AS INTEGER) AS whole_price
FROM products
ORDER BY price DESC;

solutions.Contact lines:
SELECT name || ' <' || email || '>' AS contact
FROM customers
ORDER BY contact;

solutions.Fulfillment speed:
SELECT ROUND(AVG(julianday(shipped_at) - julianday(created_at)), 2) AS avg_lead_days
FROM orders
WHERE shipped_at IS NOT NULL;

solutions.The full-lifecycle count:
SELECT COUNT(*) AS full_cycle
FROM (
  SELECT customer_id FROM orders
  GROUP BY customer_id
  HAVING COUNT(DISTINCT status) = 4
);

solutions.Category shopping lists:
SELECT category, GROUP_CONCAT(name, ', ') AS names
FROM (
  SELECT category, name FROM products ORDER BY category, name
)
GROUP BY category
ORDER BY category;

solutions.The pairing census:
SELECT COUNT(*) AS pairings
FROM products
CROSS JOIN suppliers;

solutions.Marketing-ready EU:
SELECT name, city FROM customers
WHERE region = 'EU' AND active = 1
ORDER BY name;

solutions.The premium shelf:
SELECT name, price FROM products
ORDER BY price DESC, name
LIMIT 5;

solutions.Region mates:
SELECT COUNT(*) AS region_pairs
FROM customers a
JOIN customers b ON a.region = b.region AND a.id < b.id;

solutions.Pending right now:
SELECT c.name FROM customers c
WHERE EXISTS (
  SELECT 1 FROM orders o
  WHERE o.customer_id = c.id AND o.status = 'pending'
)
ORDER BY c.name;

