WHERE id = 1;

solutions.The wishlists table:
CREATE TABLE wishlists (
  id          INTEGER PRIMARY KEY,
  customer_id INTEGER NOT NULL REFERENCES customers(id),
  product_id  INTEGER NOT NULL REFERENCES products(id),
  added_at    TEXT NOT NULL
);

solutions.Coupons with teeth:
CREATE TABLE coupons (
  id     INTEGER PRIMARY KEY,
  code   TEXT NOT NULL UNIQUE,
  pct    INTEGER NOT NULL CHECK (pct BETWEEN 1 AND 50),
  active INTEGER NOT NULL DEFAULT 1
);

solutions.An audit trail that timestamps itself:
CREATE TABLE audit_log (
  id     INTEGER PRIMARY KEY,
  at     TEXT NOT NULL DEFAULT (datetime('now')),
  action TEXT NOT NULL
);

solutions.Refunds, fenced twice:
CREATE TABLE refunds (
  id       INTEGER PRIMARY KEY,
  order_id INTEGER NOT NULL REFERENCES orders(id),
  amount   REAL NOT NULL CHECK (amount > 0),
  reason   TEXT
);

solutions.The status ledger:
CREATE TABLE order_status_log (
  status      TEXT PRIMARY KEY,
  transitions INTEGER NOT NULL DEFAULT 0
);

solutions.The orders contract, read back:
