solutions.Count to ten:
WITH RECURSIVE seq(n) AS (
  SELECT 1
  UNION ALL
  SELECT n + 1 FROM seq WHERE n < 10
)
SELECT n FROM seq;

solutions.The countdown:
WITH RECURSIVE t(n) AS (
  SELECT 5
  UNION ALL
  SELECT n - 1 FROM t WHERE n > 1
)
SELECT n FROM t;

solutions.Powers of two:
WITH RECURSIVE t(n) AS (
  SELECT 1
  UNION ALL
  SELECT n * 2 FROM t WHERE n < 64
)
SELECT n FROM t;

solutions.The January day spine:
WITH RECURSIVE days(d) AS (
  SELECT date('2024-01-01')
  UNION ALL
  SELECT date(d, '+1 day') FROM days WHERE d < '2024-01-31'
)
SELECT d FROM days;

